  1→package jlsm.sstable;
  2→
  3→import jlsm.bloom.blocked.BlockedBloomFilter;
  4→import jlsm.core.bloom.BloomFilter;
  5→import jlsm.core.model.Entry;
  6→import jlsm.core.model.Level;
  7→import jlsm.core.model.SequenceNumber;
  8→import jlsm.core.sstable.SSTableMetadata;
  9→import jlsm.core.sstable.SSTableWriter;
 10→import jlsm.sstable.internal.DataBlock;
 11→import jlsm.sstable.internal.EntryCodec;
 12→import jlsm.sstable.internal.SSTableFormat;
 13→
 14→import java.io.IOException;
 15→import java.lang.foreign.MemorySegment;
 16→import java.lang.foreign.ValueLayout;
 17→import java.nio.ByteBuffer;
 18→import java.nio.channels.FileChannel;
 19→import java.nio.channels.SeekableByteChannel;
 20→import java.nio.file.Files;
 21→import java.nio.file.Path;
 22→import java.nio.file.StandardOpenOption;
 23→import java.util.ArrayList;
 24→import java.util.List;
 25→import java.util.Objects;
 26→
 27→/**
 28→ * Writes entries to a new SSTable file using a trie-based key index.
 29→ *
 30→ * <p>
 31→ * State machine: {@code OPEN → FINISHED → CLOSED} and {@code OPEN → CLOSED}. Calling
 32→ * {@link #close()} without {@link #finish()} deletes the partial file.
 33→ */
 34→public final class TrieSSTableWriter implements SSTableWriter {
 35→
 36→    private enum State {
 37→        OPEN, FINISHED, CLOSED
 38→    }
 39→
 40→    private final long id;
 41→    private final Level level;
 42→    private final Path outputPath;
 43→    private final SeekableByteChannel channel;
 44→
 45→    // Data block accumulation
 46→    private DataBlock currentBlock = new DataBlock();
 47→    private long writePosition = 0L;
 48→
 49→    // Index: parallel lists of keys (raw byte[]) + file offsets
 50→    private final List<byte[]> indexKeys = new ArrayList<>();
 51→    private final List<Long> indexOffsets = new ArrayList<>();
 52→
 53→    // Bloom filter
 54→    private BloomFilter bloomFilter;
 55→    private final BloomFilter.Factory bloomFactory;
 56→
 57→    // Stats
 58→    private long entryCount = 0L;
 59→    private long approximateSizeBytes = 0L;
 60→    private MemorySegment smallestKey = null;
 61→    private MemorySegment largestKey = null;
 62→    private SequenceNumber minSequence = null;
 63→    private SequenceNumber maxSequence = null;
 64→
 65→    // Previous key for ordering check
 66→    private byte[] lastKeyBytes = null;
 67→
 68→    private State state = State.OPEN;
 69→
 70→    /**
 71→     * Creates a new writer that will write to {@code outputPath} using a {@link BlockedBloomFilter}
 72→     * with 1% target false-positive rate.
 73→     *
 74→     * @param id unique SSTable identifier
 75→     * @param level LSM level for this SSTable
 76→     * @param outputPath path to the output file; must not exist
 77→     * @throws IOException if the file cannot be opened
 78→     */
 79→    public TrieSSTableWriter(long id, Level level, Path outputPath) throws IOException {
 80→        this(id, level, outputPath, n -> new BlockedBloomFilter(n, 0.01));
 81→    }
 82→
 83→    /**
 84→     * Creates a new writer that will write to {@code outputPath} using a custom bloom filter
 85→     * factory. The factory is invoked at {@link #finish()} time with the actual entry count.
 86→     *
 87→     * @param id unique SSTable identifier
 88→     * @param level LSM level for this SSTable
 89→     * @param outputPath path to the output file; must not exist
 90→     * @param bloomFactory factory used to create the bloom filter; must not be null
 91→     * @throws IOException if the file cannot be opened
 92→     */
 93→    public TrieSSTableWriter(long id, Level level, Path outputPath,
 94→            BloomFilter.Factory bloomFactory) throws IOException {
 95→        Objects.requireNonNull(level, "level must not be null");
 96→        Objects.requireNonNull(outputPath, "outputPath must not be null");
 97→        Objects.requireNonNull(bloomFactory, "bloomFactory must not be null");
 98→        this.id = id;
 99→        this.level = level;
100→        this.outputPath = outputPath;
101→        this.bloomFactory = bloomFactory;
102→        this.channel = Files.newByteChannel(outputPath, StandardOpenOption.CREATE_NEW,
103→                StandardOpenOption.WRITE);
104→    }
105→
106→    @Override
107→    public void append(Entry entry) throws IOException {
108→        Objects.requireNonNull(entry, "entry must not be null");
109→        if (state != State.OPEN) {
110→            throw new IllegalStateException("writer is not open (state=" + state + ")");
111→        }
112→
113→        byte[] keyBytes = entry.key().toArray(ValueLayout.JAVA_BYTE);
114→
115→        // Enforce strictly ascending key order
116→        if (lastKeyBytes != null) {
117→            int cmp = compareUnsigned(keyBytes, lastKeyBytes);
118→            if (cmp <= 0) {
119→                throw new IllegalArgumentException(
120→                        "keys must be strictly ascending; got key not greater than previous key");
121→            }
122→        }
123→
124→        // Encode using the already-extracted key bytes to avoid a redundant toArray
125→        byte[] encoded = EntryCodec.encode(entry, keyBytes);
126→
127→        // Absolute file offset of this entry: block start + block's current byte size.
128→        // currentBlock.byteSize() includes the 4-byte count header plus all previously encoded
129→        // entries, so this points to the byte immediately after the last written entry.
130→        long entryAbsOffset = writePosition + currentBlock.byteSize();
131→
132→        // Store raw byte[] — avoids MemorySegment round-trip in writeKeyIndex
133→        indexKeys.add(keyBytes);
134→        indexOffsets.add(entryAbsOffset);
135→
136→        currentBlock.add(encoded);
137→        approximateSizeBytes += encoded.length;
138→
139→        // Update stats — reuse keyBytes; clone only for smallest (first entry)
140→        SequenceNumber seq = entry.sequenceNumber();
141→        if (smallestKey == null)
142→            smallestKey = MemorySegment.ofArray(keyBytes.clone());
143→        largestKey = MemorySegment.ofArray(keyBytes);
144→
145→        if (minSequence == null || seq.compareTo(minSequence) < 0)
146→            minSequence = seq;
147→        if (maxSequence == null || seq.compareTo(maxSequence) > 0)
148→            maxSequence = seq;
149→
150→        lastKeyBytes = keyBytes;
151→        entryCount++;
152→
153→        // Flush block if it exceeds the target size
154→        if (currentBlock.byteSize() >= SSTableFormat.DEFAULT_BLOCK_SIZE) {
155→            flushCurrentBlock();
156→        }
157→    }
158→
159→    private void flushCurrentBlock() throws IOException {
160→        if (currentBlock.count() == 0)
161→            return;
162→        byte[] blockBytes = currentBlock.serialize();
163→        writeBytes(blockBytes);
164→        currentBlock = new DataBlock();
165→    }
166→
167→    private void writeBytes(byte[] bytes) throws IOException {
168→        ByteBuffer buf = ByteBuffer.wrap(bytes);
169→        while (buf.hasRemaining()) {
170→            channel.write(buf);
171→        }
172→        writePosition += bytes.length;
173→    }
174→
175→    @Override
176→    public SSTableMetadata finish() throws IOException {
177→        if (state != State.OPEN) {
178→            throw new IllegalStateException("finish() already called or writer is closed");
179→        }
180→        if (entryCount == 0) {
181→            throw new IllegalStateException("cannot finish an empty SSTable");
182→        }
183→
184→        // Flush remaining block
185→        flushCurrentBlock();
186→
187→        // Build bloom filter
188→        bloomFilter = bloomFactory.create((int) Math.max(1, entryCount));
189→        for (byte[] key : indexKeys) {
190→            bloomFilter.add(MemorySegment.ofArray(key));
191→        }
192→
193→        // Write key index
194→        long indexOffset = writePosition;
195→        writeKeyIndex();
196→        long indexLength = writePosition - indexOffset;
197→
198→        // Write bloom filter
199→        long filterOffset = writePosition;
200→        MemorySegment filterBytes = bloomFilter.serialize();
201→        byte[] filterArray = filterBytes.toArray(ValueLayout.JAVA_BYTE);
202→        writeBytes(filterArray);
203→        long filterLength = writePosition - filterOffset;
204→
205→        // Write footer
206→        writeFooter(indexOffset, indexLength, filterOffset, filterLength);
207→
208→        // fsync if supported (e.g., local FileChannel; skipped for object-storage channels)
209→        if (channel instanceof FileChannel fc)
210→            fc.force(true);
211→
212→        long sizeBytes = writePosition;
213→
214→        state = State.FINISHED;
215→
216→        return new SSTableMetadata(id, outputPath, level, smallestKey, largestKey, minSequence,
217→                maxSequence, sizeBytes, entryCount);
218→    }
219→
220→    private void writeKeyIndex() throws IOException {
221→        int numKeys = indexKeys.size();
222→        // count: 4 bytes
223→        // per key: 4 (keyLen) + keyBytes + 8 (offset)
224→        int indexSize = 4;
225→        for (byte[] k : indexKeys) {
226→            indexSize += 4 + k.length + 8;
227→        }
228→        byte[] buf = new byte[indexSize];
229→        int off = 0;
230→        // numKeys
231→        buf[off++] = (byte) (numKeys >>> 24);
232→        buf[off++] = (byte) (numKeys >>> 16);
233→        buf[off++] = (byte) (numKeys >>> 8);
234→        buf[off++] = (byte) numKeys;
235→
236→        for (int i = 0; i < numKeys; i++) {
237→            byte[] keyBytes = indexKeys.get(i);
238→            int keyLen = keyBytes.length;
239→            buf[off++] = (byte) (keyLen >>> 24);
240→            buf[off++] = (byte) (keyLen >>> 16);
241→            buf[off++] = (byte) (keyLen >>> 8);
242→            buf[off++] = (byte) keyLen;
243→            System.arraycopy(keyBytes, 0, buf, off, keyLen);
244→            off += keyLen;
245→            long fileOff = indexOffsets.get(i);
246→            buf[off++] = (byte) (fileOff >>> 56);
247→            buf[off++] = (byte) (fileOff >>> 48);
248→            buf[off++] = (byte) (fileOff >>> 40);
249→            buf[off++] = (byte) (fileOff >>> 32);
250→            buf[off++] = (byte) (fileOff >>> 24);
251→            buf[off++] = (byte) (fileOff >>> 16);
252→            buf[off++] = (byte) (fileOff >>> 8);
253→            buf[off++] = (byte) fileOff;
254→        }
255→        writeBytes(buf);
256→    }
257→
258→    private void writeFooter(long idxOffset, long idxLength, long fltOffset, long fltLength)
259→            throws IOException {
260→        byte[] buf = new byte[SSTableFormat.FOOTER_SIZE];
261→        int off = 0;
262→        off = writeLong(buf, off, idxOffset);
263→        off = writeLong(buf, off, idxLength);
264→        off = writeLong(buf, off, fltOffset);
265→        off = writeLong(buf, off, fltLength);
266→        off = writeLong(buf, off, entryCount);
267→        writeLong(buf, off, SSTableFormat.MAGIC);
268→        writeBytes(buf);
269→    }
270→
271→    private static int writeLong(byte[] buf, int off, long v) {
272→        buf[off++] = (byte) (v >>> 56);
273→        buf[off++] = (byte) (v >>> 48);
274→        buf[off++] = (byte) (v >>> 40);
275→        buf[off++] = (byte) (v >>> 32);
276→        buf[off++] = (byte) (v >>> 24);
277→        buf[off++] = (byte) (v >>> 16);
278→        buf[off++] = (byte) (v >>> 8);
279→        buf[off++] = (byte) v;
280→        return off;
281→    }
282→
283→    @Override
284→    public long entryCount() {
285→        return entryCount;
286→    }
287→
288→    @Override
289→    public long approximateSizeBytes() {
290→        return approximateSizeBytes;
291→    }
292→
293→    @Override
294→    public void close() throws IOException {
295→        if (state == State.CLOSED)
296→            return;
297→        boolean shouldDelete = (state == State.OPEN);
298→        state = State.CLOSED;
299→        IOException channelEx = null;
300→        try {
301→            channel.close();
302→        } catch (IOException e) {
303→            channelEx = e;
304→        } finally {
305→            if (shouldDelete) {
306→                try {
307→                    Files.deleteIfExists(outputPath);
308→                } catch (IOException deleteEx) {
309→                    if (channelEx != null) {
310→                        channelEx.addSuppressed(deleteEx);
311→                    } else {
312→                        channelEx = deleteEx;
313→                    }
314→                }
315→            }
316→        }
317→        if (channelEx != null)
318→            throw channelEx;
319→    }
320→
321→    private static int compareUnsigned(byte[] a, byte[] b) {
322→        int len = Math.min(a.length, b.length);
323→        for (int i = 0; i < len; i++) {
324→            int cmp = Byte.compareUnsigned(a[i], b[i]);
325→            if (cmp != 0)
326→                return cmp;
327→        }
328→        return Integer.compare(a.length, b.length);
329→    }
330→}
