 1→package jlsm.sstable.internal;
 2→
 3→import jlsm.core.model.Entry;
 4→
 5→import java.util.ArrayList;
 6→import java.util.List;
 7→
 8→/**
 9→ * A mutable buffer that accumulates encoded entries for a single data block.
10→ *
11→ * <p>
12→ * Block on-disk format:
13→ *
14→ * <pre>
15→ *   [int  count  ]  4 bytes — number of entries in this block
16→ *   [entry 0 ... ]  variable
17→ * </pre>
18→ */
19→public final class DataBlock {
20→
21→    private final List<byte[]> encodedEntries = new ArrayList<>();
22→    private int byteSize = 4; // initial 4 bytes for the count field
23→
24→    /** Adds an encoded entry to this block. */
25→    public void add(byte[] encoded) {
26→        assert encoded != null : "encoded must not be null";
27→        encodedEntries.add(encoded);
28→        byteSize += encoded.length;
29→    }
30→
31→    /** Returns the current byte size of this block (including the count header). */
32→    public int byteSize() {
33→        return byteSize;
34→    }
35→
36→    /** Returns the number of entries in this block. */
37→    public int count() {
38→        return encodedEntries.size();
39→    }
40→
41→    /**
42→     * Serializes this block to a byte array.
43→     *
44→     * @return big-endian serialized form
45→     */
46→    public byte[] serialize() {
47→        byte[] buf = new byte[byteSize];
48→        int off = 0;
49→        int count = encodedEntries.size();
50→        // write count (big-endian int)
51→        buf[off++] = (byte) (count >>> 24);
52→        buf[off++] = (byte) (count >>> 16);
53→        buf[off++] = (byte) (count >>> 8);
54→        buf[off++] = (byte) count;
55→        for (byte[] entry : encodedEntries) {
56→            System.arraycopy(entry, 0, buf, off, entry.length);
57→            off += entry.length;
58→        }
59→        assert off == byteSize : "serialized size mismatch";
60→        return buf;
61→    }
62→
63→    /**
64→     * Deserializes a list of entries from a raw block byte array.
65→     *
66→     * @param blockBytes the raw block bytes
67→     * @return list of decoded entries
68→     */
69→    public static List<Entry> deserialize(byte[] blockBytes) {
70→        assert blockBytes != null : "blockBytes must not be null";
71→        assert blockBytes.length >= 4 : "block too short";
72→        int count = readInt(blockBytes, 0);
73→        assert count >= 0 : "negative entry count";
74→        List<Entry> entries = new ArrayList<>(count);
75→        int off = 4;
76→        for (int i = 0; i < count; i++) {
77→            Entry entry = EntryCodec.decode(blockBytes, off);
78→            entries.add(entry);
79→            off += EntryCodec.encodedSize(entry);
80→        }
81→        return entries;
82→    }
83→
84→    private static int readInt(byte[] buf, int off) {
85→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
86→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
87→    }
88→}
