  1→package jlsm.sstable.internal;
  2→
  3→import jlsm.core.model.Entry;
  4→import jlsm.core.model.SequenceNumber;
  5→
  6→import java.lang.foreign.MemorySegment;
  7→
  8→/**
  9→ * Encodes and decodes {@link Entry} instances to/from a compact big-endian binary format.
 10→ *
 11→ * <p>
 12→ * Entry encoding:
 13→ *
 14→ * <pre>
 15→ *   [byte  type   ]  1 byte  — 0=PUT, 1=DELETE
 16→ *   [int   keyLen ]  4 bytes — big-endian
 17→ *   [byte[] key   ]  keyLen bytes
 18→ *   [long  seqNum ]  8 bytes — big-endian
 19→ *   [int   valLen ]  4 bytes — big-endian; always present; 0 for DELETE
 20→ *   [byte[] value ]  valLen bytes — absent for DELETE
 21→ * </pre>
 22→ *
 23→ * All multi-byte fields use {@code withByteAlignment(1)} to handle unaligned offsets.
 24→ */
 25→public final class EntryCodec {
 26→
 27→    private static final byte TYPE_PUT = 0;
 28→    private static final byte TYPE_DELETE = 1;
 29→
 30→    private EntryCodec() {
 31→    }
 32→
 33→    /** Returns the encoded byte length for {@code entry} without allocating. */
 34→    public static int encodedSize(Entry entry) {
 35→        assert entry != null : "entry must not be null";
 36→        int keyLen = (int) entry.key().byteSize();
 37→        int valLen = switch (entry) {
 38→            case Entry.Put put -> (int) put.value().byteSize();
 39→            case Entry.Delete _ -> 0;
 40→        };
 41→        return 1 + 4 + keyLen + 8 + 4 + valLen;
 42→    }
 43→
 44→    /**
 45→     * Encodes {@code entry} into a new byte array.
 46→     *
 47→     * @param entry the entry to encode; must not be null
 48→     * @return encoded bytes
 49→     */
 50→    public static byte[] encode(Entry entry) {
 51→        assert entry != null : "entry must not be null";
 52→        byte[] keyBytes = entry.key().toArray(java.lang.foreign.ValueLayout.JAVA_BYTE);
 53→        return encode(entry, keyBytes);
 54→    }
 55→
 56→    /**
 57→     * Encodes {@code entry} into a new byte array, using pre-extracted key bytes to avoid a
 58→     * redundant {@link MemorySegment#toArray} call.
 59→     *
 60→     * @param entry the entry to encode; must not be null
 61→     * @param keyBytes the key bytes already extracted from {@code entry.key()}; must not be null
 62→     * @return encoded bytes
 63→     */
 64→    public static byte[] encode(Entry entry, byte[] keyBytes) {
 65→        assert entry != null : "entry must not be null";
 66→        assert keyBytes != null : "keyBytes must not be null";
 67→
 68→        byte type;
 69→        long seqNum = entry.sequenceNumber().value();
 70→        byte[] valBytes;
 71→
 72→        switch (entry) {
 73→            case Entry.Put put -> {
 74→                type = TYPE_PUT;
 75→                valBytes = put.value().toArray(java.lang.foreign.ValueLayout.JAVA_BYTE);
 76→            }
 77→            case Entry.Delete _ -> {
 78→                type = TYPE_DELETE;
 79→                valBytes = new byte[0];
 80→            }
 81→        }
 82→
 83→        int keyLen = keyBytes.length;
 84→        int valLen = valBytes.length;
 85→        byte[] buf = new byte[1 + 4 + keyLen + 8 + 4 + valLen];
 86→        int off = 0;
 87→
 88→        // type
 89→        buf[off++] = type;
 90→
 91→        // keyLen (big-endian int)
 92→        buf[off++] = (byte) (keyLen >>> 24);
 93→        buf[off++] = (byte) (keyLen >>> 16);
 94→        buf[off++] = (byte) (keyLen >>> 8);
 95→        buf[off++] = (byte) keyLen;
 96→
 97→        // key bytes
 98→        System.arraycopy(keyBytes, 0, buf, off, keyLen);
 99→        off += keyLen;
100→
101→        // seqNum (big-endian long)
102→        buf[off++] = (byte) (seqNum >>> 56);
103→        buf[off++] = (byte) (seqNum >>> 48);
104→        buf[off++] = (byte) (seqNum >>> 40);
105→        buf[off++] = (byte) (seqNum >>> 32);
106→        buf[off++] = (byte) (seqNum >>> 24);
107→        buf[off++] = (byte) (seqNum >>> 16);
108→        buf[off++] = (byte) (seqNum >>> 8);
109→        buf[off++] = (byte) seqNum;
110→
111→        // valLen (big-endian int)
112→        buf[off++] = (byte) (valLen >>> 24);
113→        buf[off++] = (byte) (valLen >>> 16);
114→        buf[off++] = (byte) (valLen >>> 8);
115→        buf[off++] = (byte) valLen;
116→
117→        // value bytes
118→        if (valLen > 0) {
119→            System.arraycopy(valBytes, 0, buf, off, valLen);
120→        }
121→
122→        return buf;
123→    }
124→
125→    /**
126→     * Decodes one {@link Entry} from {@code buf} starting at {@code offset}.
127→     *
128→     * @param buf source byte array
129→     * @param offset start position within buf
130→     * @return decoded entry
131→     */
132→    public static Entry decode(byte[] buf, int offset) {
133→        assert buf != null : "buf must not be null";
134→        assert offset >= 0 && offset < buf.length : "offset out of range";
135→
136→        int off = offset;
137→        byte type = buf[off++];
138→
139→        int keyLen = readInt(buf, off);
140→        off += 4;
141→        byte[] keyBytes = new byte[keyLen];
142→        System.arraycopy(buf, off, keyBytes, 0, keyLen);
143→        off += keyLen;
144→
145→        long seqNum = readLong(buf, off);
146→        off += 8;
147→
148→        int valLen = readInt(buf, off);
149→        off += 4;
150→
151→        MemorySegment key = MemorySegment.ofArray(keyBytes);
152→        SequenceNumber seq = new SequenceNumber(seqNum);
153→
154→        if (type == TYPE_PUT) {
155→            byte[] valBytes = new byte[valLen];
156→            if (valLen > 0) {
157→                System.arraycopy(buf, off, valBytes, 0, valLen);
158→            }
159→            return new Entry.Put(key, MemorySegment.ofArray(valBytes), seq);
160→        } else {
161→            assert type == TYPE_DELETE : "unknown entry type: " + type;
162→            return new Entry.Delete(key, seq);
163→        }
164→    }
165→
166→    private static int readInt(byte[] buf, int off) {
167→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
168→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
169→    }
170→
171→    private static long readLong(byte[] buf, int off) {
172→        return ((long) (buf[off] & 0xFF) << 56) | ((long) (buf[off + 1] & 0xFF) << 48)
173→                | ((long) (buf[off + 2] & 0xFF) << 40) | ((long) (buf[off + 3] & 0xFF) << 32)
174→                | ((long) (buf[off + 4] & 0xFF) << 24) | ((long) (buf[off + 5] & 0xFF) << 16)
175→                | ((long) (buf[off + 6] & 0xFF) << 8) | (long) (buf[off + 7] & 0xFF);
176→    }
177→}
