178→     * not throw an exception. This exercises the state machine guard (state == CLOSED early return)
179→     * and also confirms the shouldDelete logic is not re-executed.
180→     */
181→    @Test
182→    void doubleCloseWithoutFinishDoesNotThrow(@TempDir Path dir) throws IOException {
183→        Path out = dir.resolve("double_close.sst");
184→        TrieSSTableWriter w = new TrieSSTableWriter(3L, Level.L0, out);
185→        w.append(put("a", "va", 1));
186→        w.close(); // first close: OPEN -> CLOSED, file deleted
187→        assertFalse(Files.exists(out), "file must be deleted after first close()");
188→        // second close must be a no-op
189→        assertDoesNotThrow(w::close, "second close() must not throw");
190→    }
