192→    /**
193→     * Verifies that a writer that was finish()ed and then close()d does NOT delete its output file.
194→     * The shouldDelete branch must only fire when state == OPEN at close() time; a FINISHED writer
195→     * transitions to CLOSED and must leave the file intact.
196→     */
197→    @Test
198→    void closeAfterFinishPreservesFile(@TempDir Path dir) throws IOException {
199→        Path out = dir.resolve("finished_close.sst");
200→        TrieSSTableWriter w = new TrieSSTableWriter(4L, Level.L0, out);
201→        w.append(put("k", "v", 1));
202→        w.finish();
203→        w.close();
204→        assertTrue(Files.exists(out),
205→                "output file must NOT be deleted on close() after finish() was called successfully");
206→        assertTrue(Files.size(out) > 0,
207→                "output file must have non-zero size after finish() + close()");
208→    }
