383→    // -------------------------------------------------------------------------
384→    // Bloom filter Arena regression tests (Violation 2)
385→    // These tests verify that readBloomFilter() correctly deserializes the
386→    // BlockedBloomFilter regardless of which Arena strategy is used internally.
387→    // A bug in Arena.ofAuto() vs Arena.ofShared() alignment would corrupt the
388→    // deserialized bloom filter, causing false negatives on known-present keys.
389→    // -------------------------------------------------------------------------
390→
391→    /**
392→     * Verifies that the bloom filter deserialized during eager open() correctly identifies all keys
393→     * that were inserted during write. A misaligned MemorySegment in readBloomFilter() would
394→     * corrupt the filter, causing get() to return empty for a key that actually exists in the
395→     * SSTable.
396→     */
397→    @Test
398→    void eagerOpenBloomFilterCorrectlyDeserializedForAllWrittenKeys() throws IOException {
399→        Path p = dir.resolve("bloom_eager.sst");
400→        List<String> writtenKeys = List.of("apple", "banana", "cherry", "date", "elderberry");
401→        try (TrieSSTableWriter w = new TrieSSTableWriter(10L, Level.L0, p)) {
402→            for (String key : writtenKeys) {
403→                w.append(put(key, "value-" + key, writtenKeys.indexOf(key) + 1L));
404→            }
405→            w.finish();
406→        }
407→
408→        try (TrieSSTableReader r = TrieSSTableReader.open(p, BlockedBloomFilter.deserializer())) {
409→            for (String key : writtenKeys) {
410→                Optional<Entry> result = r.get(seg(key));
411→                assertTrue(result.isPresent(), "get() must return entry for key '" + key
412→                        + "'; bloom filter corruption would cause a false negative");
413→            }
414→        }
415→    }
416→
417→    /**
418→     * Verifies that the bloom filter deserialized during lazy openLazy() correctly identifies all
419→     * keys that were inserted during write. Same corruption concern as the eager path — both call
420→     * readBloomFilter() which allocates a MemorySegment.
421→     */
422→    @Test
423→    void lazyOpenBloomFilterCorrectlyDeserializedForAllWrittenKeys() throws IOException {
424→        Path p = dir.resolve("bloom_lazy.sst");
425→        List<String> writtenKeys = List.of("fig", "grape", "honeydew", "kiwi", "lemon");
426→        try (TrieSSTableWriter w = new TrieSSTableWriter(11L, Level.L0, p)) {
427→            for (String key : writtenKeys) {
428→                w.append(put(key, "value-" + key, writtenKeys.indexOf(key) + 1L));
429→            }
430→            w.finish();
431→        }
432→
433→        try (TrieSSTableReader r = TrieSSTableReader.openLazy(p,
434→                BlockedBloomFilter.deserializer())) {
435→            for (String key : writtenKeys) {
436→                Optional<Entry> result = r.get(seg(key));
437→                assertTrue(result.isPresent(), "get() must return entry for key '" + key
438→                        + "'; bloom filter corruption in lazy mode would cause a false negative");
439→            }
440→        }
441→    }
442→
443→    /**
444→     * Verifies that a key definitely absent from the SSTable is NOT returned by get(), confirming
445→     * the bloom filter was deserialized in a functional state. If the bloom filter were entirely
446→     * zeroed by an alignment bug it would report mightContain=false for every key (including
447→     * present ones), breaking all reads.
448→     */
449→    @Test
450→    void bloomFilterAfterDeserializationRejectsDefinitelyAbsentKey() throws IOException {
451→        Path p = dir.resolve("bloom_absent.sst");
452→        // Write a large set so the bloom filter has many bits set and is non-trivially correct.
453→        try (TrieSSTableWriter w = new TrieSSTableWriter(12L, Level.L0, p)) {
454→            for (int i = 0; i < 50; i++) {
455→                w.append(put(String.format("present-key-%03d", i), "v", i + 1L));
456→            }
457→            w.finish();
458→        }
459→
460→        // A key that was never written must not appear in the SSTable.
461→        // This test will fail if the bloom filter is corrupted to always return
462→        // mightContain=true AND the key index also returns a match (shouldn't happen,
463→        // but we guard the contract: get() must return empty for a key not written).
464→        try (TrieSSTableReader r = TrieSSTableReader.open(p, BlockedBloomFilter.deserializer())) {
465→            Optional<Entry> result = r.get(seg("definitely-not-present-zzzzzz"));
466→            assertTrue(result.isEmpty(),
467→                    "get() must return empty for a key that was never written");
468→        }
469→    }
470→}
